"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["868"],{95082(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.precedencia_fase.sucessora_codigo_obrigatorio","status":422,"titulo":"C\xf3digo da fase sucessora \xe9 obrigat\xf3rio"},"descricao":{"codigo":"uniplus.configuracao.precedencia_fase.sucessora_codigo_obrigatorio","requisitos":[],"oQueAconteceu":["Uma preced\xeancia liga duas fases do processo seletivo: a antecessora, que vem antes, e a sucessora, que vem depois. O cadastro (`POST /api/configuracao/admin/precedencias-fase`) trouxe o campo `sucessoraCodigo` ausente, vazio ou s\xf3 com espa\xe7os.","A recusa vem na lista `errors` da resposta, com `field` igual a `sucessoraCodigo`. Se o outro c\xf3digo tamb\xe9m tiver problema, a recusa dele vem na mesma resposta, e nada \xe9 gravado. As confer\xeancias que dependem dos dois c\xf3digos, como a de uma fase precedendo a si mesma, s\xf3 rodam quando ambos s\xe3o v\xe1lidos."],"comoResolver":["Informe o c\xf3digo da fase sucessora, uma das catorze do vocabul\xe1rio de fases (`GET /api/configuracao/vocabularios/fases-canonicas`), e envie de novo."],"ondeAparece":["Cadastro de uma preced\xeancia entre fases"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Precedencia fase"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"d146f1ba7c5762ff6b06be66801aa6e88c9be916"}}')}}]);